  async function downloadImage(){
    if(!selected.length)return;
    const logo=await logoDataUrl();
    const width=1080,rowH=154,headerH=245,height=Math.max(650,headerH+selected.length*rowH+80);
    const rows=selected.map((event,index)=>{const y=headerH+index*rowH;const month=new Date(`${event.startDate}T12:00:00`).toLocaleDateString("pt-BR",{month:"short"}).replace(".","").toUpperCase();const day=String(new Date(`${event.startDate}T12:00:00`).getDate()).padStart(2,"0");const desc=includeDescription&&event.description?event.description.slice(0,90):"";return `<g><line x1="64" y1="${y+rowH-10}" x2="1016" y2="${y+rowH-10}" stroke="#d8e2dc"/><rect x="64" y="${y+12}" width="178" height="112" rx="18" fill="${index%2?"#f47b20":"#0c503f"}"/><text x="153" y="${y+48}" text-anchor="middle" font-family="Arial" font-size="23" font-weight="700" fill="#fff">${escapeXml(month)}</text><text x="153" y="${y+99}" text-anchor="middle" font-family="Arial" font-size="52" font-weight="900" fill="#fff">${day}</text><text x="286" y="${y+48}" font-family="Arial" font-size="29" font-weight="900" fill="#123f35">${escapeXml(event.name.slice(0,46))}</text><text x="286" y="${y+82}" font-family="Arial" font-size="20" fill="#5d6d67">${escapeXml(shortDate(event))} · ${escapeXml(eventStatusLabel(event))}</text>${desc?`<text x="286" y="${y+112}" font-family="Arial" font-size="18" fill="#66746f">${escapeXml(desc)}</text>`:""}</g>`;}).join("");
    const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}"><rect width="100%" height="100%" fill="#fbfcfa"/><rect x="0" y="0" width="100%" height="18" fill="#f47b20"/><text x="64" y="82" font-family="Arial" font-size="28" font-weight="800" fill="#789b31">CALENDÁRIO INTERNO</text><text x="64" y="138" font-family="Arial" font-size="48" font-weight="900" fill="#123f35">${escapeXml(title)}</text><text x="64" y="178" font-family="Arial" font-size="20" fill="#66746f">DS Tennis · agenda gerada pelo DMP</text>${logo?`<image href="${logo}" x="790" y="42" width="220" height="130" preserveAspectRatio="xMidYMid meet"/>`:""}${rows}<text x="64" y="${height-34}" font-family="Arial" font-size="16" fill="#8a9691">Atualizado em ${escapeXml(new Date().toLocaleDateString("pt-BR"))}</text></svg>`;
    const blob=new Blob([svg],{type:"image/svg+xml;charset=utf-8"});const url=URL.createObjectURL(blob);const img=new Image();img.onload=()=>{const canvas=document.createElement("canvas");canvas.width=width;canvas.height=height;const ctx=canvas.getContext("2d");if(!ctx){URL.revokeObjectURL(url);return;}ctx.drawImage(img,0,0);URL.revokeObjectURL(url);canvas.toBlob(out=>{if(!out)return;const href=URL.createObjectURL(out);const a=document.createElement("a");a.href=href;a.download=`agenda-ds-tennis-${todayKey}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);},"image/png");};img.src=url;
  }
  function openPdf(){
    if(!selected.length)return;const popup=window.open("","_blank");if(!popup)return;const rows=selected.map(event=>`<article><div class="date"><b>${escapeHtml(new Date(`${event.startDate}T12:00:00`).toLocaleDateString("pt-BR",{day:"2-digit"}))}</b><span>${escapeHtml(new Date(`${event.startDate}T12:00:00`).toLocaleDateString("pt-BR",{month:"short"}).replace(".",""))}</span></div><div><h2>${escapeHtml(event.name)}</h2><small>${escapeHtml(shortDate(event))} · ${escapeHtml(eventStatusLabel(event))}</small>${includeDescription&&event.description?`<p>${escapeHtml(event.description)}</p>`:""}</div></article>`).join("");popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(title)}</title><style>@page{size:A4;margin:14mm}body{font-family:Arial;color:#123f35;margin:0}header{display:flex;justify-content:space-between;align-items:center;border-bottom:5px solid #f47b20;padding-bottom:14px}header img{width:150px}h1{margin:0;font-size:26px}.sub{color:#789b31;font-weight:800}article{display:grid;grid-template-columns:74px 1fr;gap:16px;padding:16px 0;border-bottom:1px solid #d9e2de}.date{width:68px;height:68px;border-radius:14px;background:#0c503f;color:white;display:grid;place-content:center;text-align:center}.date b{font-size:26px}.date span{text-transform:uppercase;font-size:11px}article h2{margin:0 0 5px;font-size:18px}article small,article p{color:#66746f}article p{margin:7px 0 0}@media print{button{display:none}}</style></head><body><button onclick="print()">Imprimir / salvar PDF</button><header><div><div class="sub">CALENDÁRIO INTERNO</div><h1>${escapeHtml(title)}</h1></div><img src="${location.origin}/logo-ctds.png"></header>${rows}<script>window.onload=()=>setTimeout(()=>window.print(),350)<\/script></body></html>`);popup.document.close();
  }
  function downloadList(){
    if(!selected.length)return;const lines=[title,"DS Tennis","",...selected.flatMap(event=>[`${shortDate(event)} — ${event.name}${confirmedOnly?"":" · "+eventStatusLabel(event)}`,includeDescription&&event.description?event.description:"",""]).filter(Boolean)];const blob=new Blob([lines.join("\n")],{type:"text/plain;charset=utf-8"});const href=URL.createObjectURL(blob);const a=document.createElement("a");a.href=href;a.download=`agenda-ds-tennis-${todayKey}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);
  }
  const generate=()=>format==="IMAGE"?void downloadImage():format==="PDF"?openPdf():downloadList();
  return <div className={styles.modalBackdrop}><section className={`${styles.modal} ${styles.eventExportModal}`}>
    <div className={styles.modalHead}><div><h2>Exportar agenda</h2><p>Gere uma arte pronta para WhatsApp, PDF ou lista simples.</p></div><button onClick={onClose}>×</button></div>
    <div className={styles.exportControls}>
      <label>Período<select value={period} onChange={e=>setPeriod(e.target.value as typeof period)}><option value="UPCOMING">Próximos eventos</option><option value="MONTH">Este mês</option><option value="SEMESTER">Semestre atual</option><option value="YEAR">Ano {defaultYear}</option><option value="CUSTOM">Escolher período</option></select></label>
      <label>Formato<select value={format} onChange={e=>setFormat(e.target.value as typeof format)}><option value="IMAGE">Imagem para WhatsApp</option><option value="PDF">PDF</option><option value="LIST">Lista simples</option></select></label>
      {period==="CUSTOM"?<><label>De<input type="date" value={customStart} onChange={e=>setCustomStart(e.target.value)}/></label><label>Até<input type="date" value={customEnd} onChange={e=>setCustomEnd(e.target.value)}/></label></>:null}
    </div>
    <div className={styles.exportChecks}><label><input type="checkbox" checked={confirmedOnly} onChange={e=>setConfirmedOnly(e.target.checked)}/> Somente eventos confirmados</label><label><input type="checkbox" checked={includeDescription} onChange={e=>setIncludeDescription(e.target.checked)}/> Incluir descrição curta</label></div>
    <div className={styles.exportPreview}><div className={styles.exportPreviewHead}><div><small>PRÉ-VISUALIZAÇÃO</small><h3>{title}</h3></div><img src="/logo-ctds.png" alt="CT DS Tennis"/></div>{selected.length?selected.map(event=><article key={event.id}><time>{new Date(`${event.startDate}T12:00:00`).toLocaleDateString("pt-BR",{day:"2-digit",month:"short"})}</time><div><strong>{event.name}</strong><small>{shortDate(event)} · {eventStatusLabel(event)}</small>{includeDescription&&event.description?<p>{event.description}</p>:null}</div></article>):<p>Nenhum evento encontrado com estes filtros.</p>}</div>
    <div className={styles.modalActions}><button onClick={onClose}>Cancelar</button><button className={styles.primary} disabled={!selected.length} onClick={generate}>Gerar {format==="IMAGE"?"imagem":format==="PDF"?"PDF":"lista"}</button></div>
  </section></div>;
}

function KidsEventCard({event,onEdit,onDuplicate,onDelete}:{event:KidsEvent;onEdit:()=>void;onDuplicate:()=>void;onDelete:()=>void}){
  const date=event.endDate&&event.endDate!==event.startDate?`${formatDate(event.startDate)} a ${formatDate(event.endDate)}`:formatDate(event.startDate);
  const todayKey=new Intl.DateTimeFormat("en-CA",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
  const past=(event.endDate||event.startDate)<todayKey;
  const status=event.status||(past?"COMPLETED":"PROGRAMMED");
  const statusLabels:Record<NonNullable<KidsEvent["status"]>,string>={PROGRAMMED:"Programado",CONFIRMED:"Confirmado",COMPLETED:"Concluído",CANCELLED:"Cancelado"};
  const typeLabels:Record<NonNullable<KidsEvent["type"]>,string>={CLINIC:"Clínica",TMC_ADULT:"TMC Adulto",TMC_KIDS:"TMC Kids",RANKING:"Ranking",INTERNAL:"Evento interno",OTHER:"Outro"};
  return <article className={`${styles.eventCard} ${status==="COMPLETED"||status==="CANCELLED"?styles.eventPast:""}`}>
    <div className={styles.eventDate}><span>{new Date(`${event.startDate}T12:00:00`).toLocaleDateString("pt-BR",{month:"short"}).replace(".","")}</span><strong>{new Date(`${event.startDate}T12:00:00`).getDate()}</strong></div>
    <div className={styles.eventInfo}>
      <small>{date}</small>
      <h3>{event.name}</h3>
      <div className={styles.eventMeta}><span>{typeLabels[event.type||"OTHER"]}</span><span>{statusLabels[status]}</span></div>
      {event.description?<p>{event.description}</p>:null}
      {event.notes?<small className={styles.eventNotes}>Obs.: {event.notes}</small>:null}
    </div>
    <div className={styles.eventActions}>
      {event.driveUrl?<a href={event.driveUrl} target="_blank" rel="noreferrer">📁 Abrir pasta</a>:null}
      <button onClick={onEdit}>Editar</button>
      <button onClick={onDuplicate}>Duplicar</button>
      <button className={styles.dangerButton} onClick={onDelete}>Excluir</button>
    </div>
  </article>;
}

function KidsEventEditor({event,onClose,onSave}:{event:KidsEvent;onClose:()=>void;onSave:(event:KidsEvent)=>void}){
  const [draft,setDraft]=useState<KidsEvent>({...event});
  const statusOptions:[NonNullable<KidsEvent["status"]>,string][]=[["PROGRAMMED","Programado"],["CONFIRMED","Confirmado"],["COMPLETED","Concluído"],["CANCELLED","Cancelado"]];
  const typeOptions:[NonNullable<KidsEvent["type"]>,string][]=[["CLINIC","Clínica"],["TMC_ADULT","TMC Adulto"],["TMC_KIDS","TMC Kids"],["RANKING","Ranking"],["INTERNAL","Evento interno"],["OTHER","Outro"]];
  const valid=Boolean(draft.name.trim()&&draft.startDate&&(!draft.endDate||draft.endDate>=draft.startDate));
  return <div className={styles.modalBackdrop}><section className={styles.modal}>
    <div className={styles.modalHead}><div><h2>{event.name?"Editar evento":"Novo evento"}</h2><p>Cadastre ou atualize as informações do evento.</p></div><button onClick={onClose}>×</button></div>
    <div className={styles.formGrid}>
      <label className={styles.eventFormFull}>Título do evento<input autoFocus value={draft.name} onChange={e=>setDraft(current=>({...current,name:e.target.value}))} placeholder="Nome do evento"/></label>
      <label>Data inicial<input type="date" value={draft.startDate} onChange={e=>setDraft(current=>({...current,startDate:e.target.value,year:Number(e.target.value.slice(0,4))||current.year}))}/></label>
      <label>Data final<input type="date" min={draft.startDate} value={draft.endDate||draft.startDate} onChange={e=>setDraft(current=>({...current,endDate:e.target.value}))}/></label>
      <label>Tipo<select value={draft.type||"OTHER"} onChange={e=>setDraft(current=>({...current,type:e.target.value as NonNullable<KidsEvent["type"]>}))}>{typeOptions.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>
      <label>Status<select value={draft.status||"PROGRAMMED"} onChange={e=>setDraft(current=>({...current,status:e.target.value as NonNullable<KidsEvent["status"]>}))}>{statusOptions.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>
      <label className={styles.eventFormFull}>Descrição<textarea rows={3} value={draft.description||""} onChange={e=>setDraft(current=>({...current,description:e.target.value}))} placeholder="Descrição do evento"/></label>
      <label className={styles.eventFormFull}>Observações internas<textarea rows={2} value={draft.notes||""} onChange={e=>setDraft(current=>({...current,notes:e.target.value}))} placeholder="Observações internas"/></label>
      <label className={styles.eventFormFull}>Pasta do Google Drive<input value={draft.driveUrl||""} onChange={e=>setDraft(current=>({...current,driveUrl:e.target.value}))} placeholder="Cole o link da pasta (opcional)"/></label>
    </div>
    <div className={styles.modalActions}><button onClick={onClose}>Cancelar</button><button className={styles.primary} disabled={!valid} onClick={()=>onSave({...draft,name:draft.name.trim(),description:draft.description?.trim(),notes:draft.notes?.trim(),driveUrl:draft.driveUrl?.trim(),endDate:draft.endDate||draft.startDate,year:Number(draft.startDate.slice(0,4))})}>Salvar evento</button></div>
  </section></div>;
}

function ReplacementBoard({replacements,students}:{replacements:KidsReplacement[];students:{id:string;name:string}[]}){
  const studentName=(id:string)=>students.find(item=>item.id===id)?.name||"Aluno";
  const sections:[KidsReplacement["status"],string][]=[["PENDING","Pendentes"],["SCHEDULED","Agendadas"],["COMPLETED","Utilizadas"]];
  return <div className={styles.grid2}>{sections.map(([status,label])=><article key={status} className={styles.cancelBox}><h3>{label} · {replacements.filter(item=>item.status===status).length}</h3>{replacements.filter(item=>item.status===status).sort((a,b)=>localeCompare(studentName(a.studentId),studentName(b.studentId))).map(item=><div key={item.id} className={styles.replacementLine}><strong>{studentName(item.studentId)}</strong><small>{status==="PENDING"?`Aula perdida em ${formatDate(item.sourceDate)}`:status==="SCHEDULED"?`Marcada para ${formatDate(item.scheduledDate||item.sourceDate)}`:`Reposta em ${formatDate(item.completedDate||item.scheduledDate||item.sourceDate)}${item.attendance==="ABSENT"?" · faltou, crédito consumido":""}`}</small></div>)}</article>)}</div>;
}



function ReplacementLessonForm({
  replacements,
  students,
  classes,
  lessons,
  onClose,
  onSave,
}: {
  replacements: KidsReplacement[];
  students: KidsStudent[];
  classes: KidsClass[];
  lessons: KidsLesson[];
  onClose: () => void;
  onSave: (input: {date:string;startTime:string;endTime:string;category:KidsCategory;studentIds:string[];classId?:string;rosterMode:"LEVEL_ALL"|"CUSTOM"}) => void;
}) {
  void replacements;
  void lessons;
  void students;
  const [date,setDate]=useState(localDate());
  const [startTime,setStartTime]=useState("16:00");
  const [endTime,setEndTime]=useState("17:00");
  const [category,setCategory]=useState<KidsCategory>("RED");
  const [classId,setClassId]=useState("");
  const [selected,setSelected]=useState<string[]>([]);
  const [showOtherStudents,setShowOtherStudents]=useState(false);
  const [otherStudentSearch,setOtherStudentSearch]=useState("");

  const activeClasses=classes.filter(item=>item.active).sort((a,b)=>localeCompare(a.name,b.name));
  const activeStudents=Array.from(new Map(
    classes.flatMap(group=>group.students).filter(item=>item.active).map(item=>[item.id,item] as const)
  ).values()).sort((a,b)=>localeCompare(a.name,b.name));
  const destinationClass=activeClasses.find(item=>item.id===classId);
  const selectedCategory=destinationClass?.category||category;
  const levelStudentIds=Array.from(new Set(
    classes
      .filter(group=>group.active&&group.category===selectedCategory)
      .flatMap(group=>group.students.filter(student=>student.active).map(student=>student.id))
  ));
  const levelStudentIdSet=new Set(levelStudentIds);
  const levelStudents=activeStudents.filter(student=>levelStudentIdSet.has(student.id));
  const selectedOtherStudents=activeStudents.filter(student=>selected.includes(student.id)&&!levelStudentIdSet.has(student.id));
  const normalizedOtherSearch=normalizeName(otherStudentSearch.trim());
  const otherStudents=activeStudents.filter(student=>
    !levelStudentIdSet.has(student.id)
    &&(!normalizedOtherSearch||normalizeName(student.name).includes(normalizedOtherSearch))
  );
  const selectedLevelCount=levelStudentIds.filter(id=>selected.includes(id)).length;

  function studentLevels(id:string){
    return Array.from(new Set(classes.filter(group=>group.active&&group.students.some(student=>student.id===id&&student.active)).map(group=>categoryLabel[group.category]))).join(" / ")||"Outro nível";
  }

  function toggleStudent(id:string) {
    setSelected(current=>current.includes(id)?current.filter(item=>item!==id):[...current,id]);
  }

  function selectAllLevel() {
    setSelected(current=>Array.from(new Set([...current.filter(id=>!levelStudentIdSet.has(id)),...levelStudentIds])));
  }

  function save() {
    if(!date||!selected.length)return;
    const selectedLevelIds=selected.filter(id=>levelStudentIdSet.has(id));
    const selectedOtherIds=selected.filter(id=>!levelStudentIdSet.has(id));
    const rosterMode =
      selectedOtherIds.length===0 &&
      selectedLevelIds.length===levelStudentIds.length &&
      levelStudentIds.every(id=>selectedLevelIds.includes(id))
        ? "LEVEL_ALL" as const
        : "CUSTOM" as const;
    onSave({
      date,
      startTime:destinationClass?.startTime||startTime,
      endTime:destinationClass?.endTime||endTime,
      category:selectedCategory,
      studentIds:selected,
      classId:destinationClass?.id,
      rosterMode,
    });
  }

  return <div className={styles.modalBackdrop}>
    <section className={styles.modal}>
      <div className={styles.modalHead}>
        <div>
          <h2>Reposição individual</h2>
          <p>Escolha a criança e onde ela fará a aula. Não é necessário vincular uma aula cancelada.</p>
        </div>
        <button onClick={onClose}>Fechar</button>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:12}}>
        <label style={{gridColumn:"1 / -1"}}>
          Turma onde fará a reposição
          <select value={classId} onChange={event=>{setClassId(event.target.value);setSelected([]);setShowOtherStudents(false);setOtherStudentSearch("");}}>
            <option value="">Aula avulsa / sem turma específica</option>
            {activeClasses.map(group=><option key={group.id} value={group.id}>{group.name}</option>)}
          </select>
        </label>
        <label>
          Data
          <input type="date" value={date} onChange={event=>setDate(event.target.value)}/>
        </label>
        {!destinationClass?<label>
          Bola
          <select value={category} onChange={event=>{setCategory(event.target.value as KidsCategory);setSelected([]);setShowOtherStudents(false);setOtherStudentSearch("");}}>
            <option value="RED">Vermelha</option>
            <option value="ORANGE">Laranja</option>
            <option value="GREEN">Verde</option>
            <option value="YELLOW">Amarela</option>
          </select>
        </label>:<label>
          Aula escolhida
          <input value={destinationClass.name} readOnly/>
        </label>}
        {!destinationClass?<><label>
          Início
          <input type="time" value={startTime} onChange={event=>setStartTime(event.target.value)}/>
        </label>
        <label>
          Fim
          <input type="time" value={endTime} onChange={event=>setEndTime(event.target.value)}/>
        </label></>:null}
      </div>

      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,flexWrap:"wrap",marginTop:16}}>
        <div>
          <h3 style={{margin:0}}>Crianças convidadas ({selected.length})</h3>
          <p className="muted" style={{margin:"4px 0 0"}}>Pode lançar reposição mesmo com saldo zero ou positivo. Depois de selecionar todos do nível, desmarque individualmente quem não participará.</p>
        </div>
        <button type="button" onClick={selectAllLevel} disabled={!levelStudentIds.length}>
          Selecionar todos da Bola {categoryLabel[selectedCategory]} ({levelStudentIds.length})
        </button>
      </div>

      <div style={{margin:"8px 0 10px",fontSize:13}}>
        {selectedLevelCount} de {levelStudentIds.length} alunos da Bola {categoryLabel[selectedCategory]} selecionados.
      </div>

      <div className={styles.lessonList} style={{maxHeight:320,overflowY:"auto"}}>
        {levelStudents.map(student=><label key={student.id} className={styles.lessonRow}>
          <span><strong>{student.name}</strong><small>{selected.includes(student.id)?"Selecionada para esta reposição":"Toque para selecionar"}</small></span>
          <input type="checkbox" checked={selected.includes(student.id)} onChange={()=>toggleStudent(student.id)}/>
        </label>)}
        {!levelStudents.length?<div className={styles.empty}><strong>Nenhum aluno ativo nesta bola</strong><span>Você ainda pode adicionar manualmente uma criança de outro nível.</span></div>:null}
      </div>

      <div className={styles.otherStudentsBlock}>
        {selectedOtherStudents.length?<div className={styles.selectedOtherStudents}>
          <strong>Alunos adicionados de outro nível</strong>
          {selectedOtherStudents.map(student=><div key={student.id}><span><b>{student.name}</b><small>Bola {studentLevels(student.id)}</small></span><button type="button" onClick={()=>toggleStudent(student.id)}>Remover</button></div>)}
        </div>:null}
        <button type="button" className={styles.addOtherStudentButton} onClick={()=>setShowOtherStudents(current=>!current)}>
          {showOtherStudents?"Fechar seleção adicional":"+ Adicionar aluno de outro nível"}
        </button>
        {showOtherStudents?<div className={styles.otherStudentsPicker}>
          <input value={otherStudentSearch} onChange={event=>setOtherStudentSearch(event.target.value)} placeholder="Buscar aluno de outro nível..." autoFocus/>
          <div className={styles.lessonList}>
            {otherStudents.map(student=><label key={student.id} className={styles.lessonRow}>
              <span><strong>{student.name}</strong><small>Bola {studentLevels(student.id)}</small></span>
              <input type="checkbox" checked={selected.includes(student.id)} onChange={()=>toggleStudent(student.id)}/>
            </label>)}
            {!otherStudents.length?<small className={styles.otherStudentsEmpty}>Nenhum outro aluno encontrado.</small>:null}
          </div>
        </div>:null}
      </div>

      <div className={styles.modalActions}>
        <button onClick={onClose}>Cancelar</button>
        <button className={styles.primary} disabled={!selected.length||!date} onClick={save}>
          Salvar reposição
        </button>
      </div>
    </section>
  </div>;
}
function Stat({
  label,
  value,
  suffix = "",
  icon,
  onClick,
}: {
  label: string;
  value: number;
  suffix?: string;
  icon: string;
  onClick: () => void;
}) {
  return (
    <button className={styles.stat} onClick={onClick}>
      <span>{icon}</span>
      <div>
        <small>{label}</small>
        <strong>
          {value}
          {suffix}
        </strong>
      </div>
      <b>›</b>
    </button>
  );
}
function Empty({ title, text }: { title: string; text: string }) {
  return (
    <div className={styles.empty}>
      <strong>{title}</strong>
      <span>{text}</span>
    </div>
  );
}
function CategoryDot({ category }: { category: KidsCategory }) {
  return (
    <i
      className={`${styles.ball} ${styles[category.toLowerCase()]}`}
      title={`Bola ${categoryLabel[category]}`}
    />
  );
}
function LessonRow({
  lesson,
  group,
  fifthReplacement=false,
  onClick,
}: {
  lesson: KidsLesson;
  group?: KidsClass;
  fifthReplacement?: boolean;
  onClick: () => void;
}) {
  if (!group) return null;
  const participantIds=lesson.kind==="REPLACEMENT"
    ? [...new Set(lesson.replacementStudentIds||[])]
    : group.students.filter(item=>item.active&&(!item.startDate||item.startDate<=lesson.date)).map(item=>item.id);
  const present = participantIds.filter(
    (studentId) => lesson.attendance[studentId] !== "ABSENT",
  ).length;
  return (
    <button className={styles.lessonRow} onClick={onClick}>
      <CategoryDot category={group.category} />
      <span>
        <strong>
          {formatDate(lesson.date)} · {group.startTime} · {group.name}
        </strong>
        <small>
          {fifthReplacement ? "5ª aula do mês — reposição · Já contabilizada · " : ""}
          {lesson.status === "SCHEDULED" && lessonHasPassed(lesson, [group])
            ? "Realizada"
            : statusLabel[lesson.status]}
          {lesson.status === "CANCELLED" && cancelReasonText(lesson)
            ? ` · ${cancelReasonText(lesson)}`
            : ""}
          {lesson.theme ? ` — ${lesson.theme}` : ""}
          {lesson.status === "COMPLETED"
            ? ` · ${present}/${participantIds.length} presentes`
            : ""}
          {lesson.replacementStatus !== "NONE"
            ? ` · Reposição ${lesson.replacementStatus.toLowerCase()}`
            : ""}
        </small>
      </span>
      <b>Abrir</b>
    </button>
  );
}

function LessonEditor({
  lesson,
  group,
  replacements,
  allStudents,
  onClose,
  onSave,
}: {
  lesson: KidsLesson;
  group: KidsClass;
  replacements:KidsReplacement[];
  allStudents:KidsStudent[];
  onClose: () => void;
  onSave: (next: KidsLesson) => void | Promise<void>;
}) {
  const [draft, setDraft] = useState({
    ...lesson,
    attendance: { ...lesson.attendance },
  });
  const [replacementStudent,setReplacementStudent]=useState("");
  const [showChamadaSearch,setShowChamadaSearch]=useState(false);
  const [chamadaSearch,setChamadaSearch]=useState("");
  const [editorSaving,setEditorSaving]=useState(false);
  const saveInFlight=useRef(false);
  const [rosterCorrectionMode,setRosterCorrectionMode]=useState(false);
  const replacementLesson=draft.kind==="REPLACEMENT";
  const hasReplacementRoster=replacementLesson||Boolean(draft.replacementStudentIds?.length);
  const rosterLocked=hasReplacementRoster&&(draft.status==="COMPLETED"||Boolean(draft.replacementRosterLocked));
  const regularChamadaEditable=!replacementLesson&&["SCHEDULED","COMPLETED"].includes(draft.status);
  const rosterEditable=(hasReplacementRoster||regularChamadaEditable)&&(!rosterLocked||rosterCorrectionMode);
  const regularStudents = (replacementLesson ? [] : group.students)
    .filter(
      (item) =>
        item.active && (!item.startDate || item.startDate <= lesson.date),
    )
  const extraStudents=(draft.replacementStudentIds||[]).map(id=>allStudents.find(item=>item.id===id)).filter(Boolean) as KidsStudent[];
  const students=[...regularStudents,...extraStudents.filter(item=>!regularStudents.some(regular=>regular.id===item.id))].sort((a,b)=>localeCompare(a.name,b.name));
  const pendingStudents=replacements.filter(item=>item.status==="PENDING").map(item=>allStudents.find(student=>student.id===item.studentId)).filter((item,index,array):item is KidsStudent=>Boolean(item)&&array.findIndex(candidate=>candidate?.id===item?.id)===index).filter(item=>!students.some(current=>current.id===item.id)).sort((a,b)=>localeCompare(a.name,b.name));
  const rosterIds=[...new Set(draft.replacementStudentIds||[])];
  const presentCount=rosterIds.filter(id=>draft.attendance[id]!=="ABSENT").length;
  const absentCount=rosterIds.filter(id=>draft.attendance[id]==="ABSENT").length;
  useEffect(() => {
    if (
      draft.status !== "HOLIDAY" &&
      Object.keys(draft.attendance).length === 0
    )
      setDraft((current) => ({
        ...current,
        attendance: Object.fromEntries(
          students.map((item) => [item.id, "PRESENT"]),
        ),
      }));
  }, []);
  function toggle(id: string) {
    setDraft((current) => ({
      ...current,
      absenceReplacementRights: {...current.absenceReplacementRights,[id]: false},
      attendance: {
        ...current.attendance,
        [id]: current.attendance[id] === "ABSENT" ? "PRESENT" : "ABSENT",
      },
    }));
  }
  function allPresent() {
    setDraft((current) => ({
      ...current,
      absenceReplacementRights: {},
      attendance: Object.fromEntries(
        students.map((item) => [item.id, "PRESENT"]),
      ),
    }));
  }
  function removeReplacementStudent(studentId:string){
    if(!rosterEditable)return;
    const student=allStudents.find(item=>item.id===studentId);
    const message=rosterLocked
      ? `Remover ${student?.name||"esta criança"} desta reposição já realizada?\n\nUse esta correção somente se a criança foi incluída por engano. Uma falta deve continuar marcada como falta e não devolve o crédito.`
      : `Remover ${student?.name||"esta criança"} da lista desta reposição?`;
    if(!window.confirm(message))return;
    if(!replacementLesson){try{setDraft(removeChamadaReplacement(draft,studentId));}catch(error){window.alert(error instanceof Error?error.message:"Correção não permitida.");}return;}
    setDraft(current=>{
      const attendance={...current.attendance};
      delete attendance[studentId];
      const replacementStudentIds=(current.replacementStudentIds||[]).filter(id=>id!==studentId);
      return {...current,replacementStudentIds,replacementCapacity:replacementStudentIds.length,attendance};
    });
  }
  async function imageFile(file?: File) {
    if (!file) return;
    const dataUrl =
      file.type === "application/pdf"
        ? await readFile(file)
        : await compressImage(file);
    setDraft((current) => ({
      ...current,
      image: { name: file.name, dataUrl, mimeType: file.type },
    }));
  }
  function status(value: KidsLesson["status"]) {
    setDraft((current) => ({
      ...current,
      status: value,
      cancelReason:value === "CANCELLED" ? current.cancelReason : undefined,
      cancelReasonOther:value === "CANCELLED" ? current.cancelReasonOther : undefined,
      replacementEligible:
        value === "CANCELLED" ? current.replacementEligible : false,
      replacementStatus:
        value === "CANCELLED" ? current.replacementStatus : "NONE",
    }));
  }
  const cancellationReasonValid =
    draft.status !== "CANCELLED" ||
    draft.cancelReason === "RAIN" ||
    (draft.cancelReason === "OTHER" && Boolean(draft.cancelReasonOther?.trim()));
  return (
    <div className={styles.modalBackdrop}>
      <section className={styles.modal}>
        <div className={styles.modalHead}>
          <div>
            <CategoryDot category={group.category} />
            <h2>{group.name}</h2>
            <p>
              {formatDate(draft.date)} · {group.startTime} · Bola{" "}
              {categoryLabel[group.category]}
            </p>
          </div>
          <button onClick={onClose}>×</button>
        </div>
        {draft.status === "HOLIDAY" ? (
          <div className={styles.holiday}>
            Feriado — aula cancelada sem direito à reposição.
          </div>
        ) : (
          <>
            <label>
              Situação
              <select
                value={draft.status}
                onChange={(event) =>
                  status(event.target.value as KidsLesson["status"])
                }
              >
                <option value="SCHEDULED">Agendada</option>
                <option value="COMPLETED">Realizada</option>
                <option value="CANCELLED">Aula cancelada</option>
              </select>
            </label>
            {draft.status === "CANCELLED" ? (
              <div className={styles.cancelBox}>
                <label>
                  Motivo do cancelamento
                  <select
                    value={draft.cancelReason || ""}
                    onChange={(event) =>
                      setDraft((current) => ({
                        ...current,
                        cancelReason: event.target.value
                          ? (event.target.value as "RAIN" | "OTHER")
                          : undefined,
                        cancelReasonOther:
                          event.target.value === "OTHER"
                            ? current.cancelReasonOther
                            : undefined,
                      }))
                    }
                  >
                    <option value="">Selecione o motivo</option>
                    <option value="RAIN">Chuva</option>
                    <option value="OTHER">Outros</option>
                  </select>
                </label>
                {draft.cancelReason === "OTHER" ? (
                  <label>
                    Qual motivo?
                    <input
                      value={draft.cancelReasonOther || ""}
                      onChange={(event) =>
                        setDraft((current) => ({
                          ...current,
                          cancelReasonOther: event.target.value,
                        }))
                      }
                      placeholder="Escreva o motivo do cancelamento"
                    />
                  </label>
                ) : null}
                <label className={styles.cancelCheck}>
                  <input
                    type="checkbox"
                    checked={draft.replacementEligible}
                    onChange={(event) =>
                      setDraft((current) => ({
                        ...current,
                        replacementEligible: event.target.checked,
                        replacementStatus:
                          event.target.checked &&
                          current.replacementStatus === "NONE"
                            ? "PENDING"
                            : event.target.checked
                              ? current.replacementStatus
                              : "NONE",
                      }))
                    }
                  />{" "}
                  Aula com direito à reposição
                </label>
                {draft.replacementEligible ? (
                  <>
                    <label>
                      Situação da reposição
                      <select
                        value={draft.replacementStatus}
                        onChange={(event) =>
                          setDraft((current) => ({
                            ...current,
                            replacementStatus: event.target
                              .value as KidsLesson["replacementStatus"],
                          }))
                        }
                      >
                        <option value="PENDING">Pendente</option>
                        <option value="SCHEDULED">Agendada</option>
                        <option value="COMPLETED">Realizada</option>
                      </select>
                    </label>
                    <label>
                      Data da reposição
                      <input
                        type="date"
                        value={draft.replacementDate || ""}
                        onChange={(event) =>
                          setDraft((current) => ({
                            ...current,
                            replacementDate: event.target.value,
                          }))
                        }
                      />
                    </label>
                  </>
                ) : null}
              </div>
            ) : null}
            <div className={styles.attendanceHead}>
              <div>
                <h3>Chamada</h3>
                {hasReplacementRoster?<small>{rosterIds.length} participantes em reposição · {presentCount} presentes · {absentCount} faltas</small>:null}
              </div>
              {regularChamadaEditable?<button type="button" disabled={editorSaving} onClick={()=>setShowChamadaSearch(value=>!value)}>+ Adicionar reposição</button>:null}
              <button onClick={allPresent}>Todos presentes</button>
            </div>
            {regularChamadaEditable&&showChamadaSearch?<div className={styles.cancelBox}>
              <strong>Adicionar reposição nesta aula</strong>
              <p>{group.name} · {formatDate(draft.date)} · {group.startTime}. A turma fixa não será alterada. Confirme a inclusão em Salvar aula.</p>
              <p>O DMP permite reposição antecipada. O consumo segue a realização da aula; uma falta na reposição também consome.</p>
              <input aria-label="Buscar aluno para reposição" placeholder="Digite o nome do aluno" value={chamadaSearch} disabled={editorSaving} onChange={event=>setChamadaSearch(event.target.value)}/>
              {chamadaSearch.trim().length>=2?<div className={styles.inlineActions}>
                {allStudents.filter(student=>student.active&&(!student.startDate||student.startDate<=draft.date)&&!students.some(item=>item.id===student.id)&&normalizeName(student.name).includes(normalizeName(chamadaSearch))).map(student=><button type="button" key={student.id} disabled={editorSaving} onClick={()=>{
                  if(!window.confirm(`Adicionar ${student.name} como REPOSIÇÃO em ${group.name}, ${formatDate(draft.date)} às ${group.startTime}?\n\n${draft.status==="COMPLETED"?"A aula continuará realizada e a reposição será contabilizada ao salvar.":"A inclusão vale somente para esta aula."}`))return;
                  setDraft(current=>current.replacementStudentIds?.includes(student.id)?current:addChamadaReplacement(current,student,regularStudents.map(item=>item.id)));setChamadaSearch("");setShowChamadaSearch(false);
                }}>{student.name} · Adicionar</button>)}
                {!allStudents.some(student=>student.active&&(!student.startDate||student.startDate<=draft.date)&&!students.some(item=>item.id===student.id)&&normalizeName(student.name).includes(normalizeName(chamadaSearch)))?<p>Nenhum aluno disponível com esse nome.</p>:null}
              </div>:null}
            </div>:null}
            {hasReplacementRoster?<div className={styles.rosterIntegrityNotice}>
              <strong>{rosterLocked?"🔒 Lista protegida":"Lista de participantes"}</strong>
              <span>{rosterLocked?"A reposição já foi realizada. Uma falta continua consumindo o crédito. Se alguém foi incluído por engano, use Corrigir participantes.":"A chamada altera somente presença ou falta. Participantes podem ser corrigidos na edição abaixo."}</span>
              {rosterLocked&&!rosterCorrectionMode?<button type="button" onClick={()=>setRosterCorrectionMode(true)}>Corrigir participantes</button>:null}
              {rosterLocked&&rosterCorrectionMode?<button type="button" onClick={()=>setRosterCorrectionMode(false)}>Fechar correção</button>:null}
            </div>:null}
            {rosterEditable?<details className={styles.participantEditor} open={rosterCorrectionMode}>
              <summary>Editar participantes ({rosterIds.length})</summary>
              <div>{rosterIds.map(studentId=>{
                const student=allStudents.find(item=>item.id===studentId);
                return <p key={studentId}><span>{student?.name||"Aluno"}</span><button type="button" onClick={()=>removeReplacementStudent(studentId)}>Remover</button></p>;
              })}</div>
            </details>:null}
            {pendingStudents.length&&rosterEditable ? <div className={styles.cancelBox}>
              <strong>Adicionar criança em reposição</strong>
              <div className={styles.inlineActions}>
                <select value={replacementStudent} onChange={event=>setReplacementStudent(event.target.value)}><option value="">Selecione a criança</option>{pendingStudents.map(student=><option key={student.id} value={student.id}>{student.name}</option>)}</select>
                <button disabled={!replacementStudent} onClick={()=>{if(!replacementStudent)return;setDraft(current=>{const replacementStudentIds=[...new Set([...(current.replacementStudentIds||[]),replacementStudent])];return {...current,replacementStudentIds,replacementCapacity:replacementStudentIds.length,attendance:{...current.attendance,[replacementStudent]:"PRESENT"}}});setReplacementStudent("");}}>Adicionar</button>
              </div>
            </div>:null}
            <div className={styles.attendance}>
              {students.map((student) => {
                const value = (draft.attendance[student.id] ||
                  "PRESENT") as KidsAttendanceStatus;
                const replacementParticipant=rosterIds.includes(student.id);
                return (
                  <button
                    key={student.id}
                    className={
                      value === "PRESENT" ? styles.present : styles.absent
                    }
                    onClick={() => toggle(student.id)}
                  >
                    <span>{value === "PRESENT" ? "✓" : "×"}</span>
                    <strong>{student.name}</strong>
                    <small>{replacementParticipant?`Reposição · ${value === "PRESENT" ? "Presente" : "Falta"}`:value === "PRESENT" ? "Presente" : "Falta"}</small>
                  </button>
                );
              })}
            </div>
            {students.filter(student => draft.attendance[student.id] === "ABSENT").map(student => (
              <label key={`right:${student.id}`} className={styles.cancelBox}>
                <input type="checkbox" checked={Boolean(draft.absenceReplacementRights?.[student.id])}
                  onChange={event => setDraft(current => ({...current, absenceReplacementRights:{...current.absenceReplacementRights,[student.id]:event.target.checked}}))}/>
                {student.name} — Esta falta dá direito à reposição
              </label>
            ))}
            <div className={styles.formGrid}>
              <label>
                Tema da aula
                <textarea
                  rows={2}
                  value={draft.theme || ""}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      theme: event.target.value,
                    }))
                  }
                />
              </label>
              <label>
                Foco pedagógico
                <textarea
                  rows={2}
                  value={draft.pedagogicalFocus || ""}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      pedagogicalFocus: event.target.value,
                    }))
                  }
                />
              </label>
              <label>
                Objetivo da aula
                <textarea
                  rows={2}
                  value={draft.objective}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      objective: event.target.value,
                    }))
                  }
                />
              </label>
              <label>
                Estações / exercícios
                <textarea
                  rows={5}
                  value={(draft.stations || []).join("\n\n")}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      stations: event.target.value
                        .split(/\n\s*\n/)
                        .filter(Boolean),
                    }))
                  }
                />
              </label>
              <label>
                Dica ao professor
                <textarea
                  rows={2}
                  value={draft.teacherTip || ""}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      teacherTip: event.target.value,
                    }))
                  }
                />
              </label>
              <label>
                Plano previsto
                <textarea
                  rows={5}
                  value={draft.plannedPlan}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      plannedPlan: event.target.value,
                    }))
                  }
                />
              </label>
              <label>
                Plano realizado
                <textarea
                  rows={3}
                  value={draft.actualPlan}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      actualPlan: event.target.value,
                    }))
                  }
                />
              </label>
              <label>
                Observações
                <textarea
                  rows={3}
                  value={draft.notes}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      notes: event.target.value,
                    }))
                  }
                />
              </label>
            </div>
            <div className={styles.imageBox}>
              <strong>Anexo do plano de aula</strong>
              {draft.image ? (
                <>
                  {draft.image.mimeType === "application/pdf" ? (
                    <a
                      href={draft.image.dataUrl}
                      target="_blank"
                      rel="noreferrer"
                    >
                      📄 Abrir {draft.image.name}
                    </a>
                  ) : (
                    <img src={draft.image.dataUrl} alt={draft.image.name} />
                  )}
                  <div>
                    <label className={styles.fileButton}>
                      Substituir
                      <input
                        type="file"
                        accept="image/*,.pdf,application/pdf"
                        onChange={(event) =>
                          void imageFile(event.target.files?.[0])
                        }
                      />
                    </label>
                    <button
                      onClick={() =>
                        setDraft((current) => ({
                          ...current,
                          image: undefined,
                        }))
                      }
                    >
                      Excluir anexo
                    </button>
                  </div>
                </>
              ) : (
                <label className={styles.fileButton}>
                  Anexar imagem ou PDF
                  <input
                    type="file"
                    accept="image/*,.pdf,application/pdf"
                    onChange={(event) =>
                      void imageFile(event.target.files?.[0])
                    }
                  />
                </label>
              )}
            </div>
          </>
        )}
        <div className={styles.modalActions}>
          <button disabled={editorSaving} onClick={onClose}>Cancelar</button>
          <button
            className={styles.primary}
            disabled={editorSaving||!cancellationReasonValid||(hasReplacementRoster&&draft.status==="COMPLETED"&&!replacementRosterIsValid(draft))}
            onClick={()=>void (async()=>{
              if(saveInFlight.current)return;saveInFlight.current=true;setEditorSaving(true);
              try{await onSave({...draft,cancelReasonOther:draft.cancelReason==="OTHER"?draft.cancelReasonOther?.trim():undefined,updatedAt:new Date().toISOString()});}
              finally{saveInFlight.current=false;setEditorSaving(false);}
            })()}
          >
            Salvar aula
          </button>
        </div>
      </section>
    </div>
  );
}

function ClassEditor({
  group,
  lessons,
  semesterStart,
  semesterEnd,
  onClose,
  onSave,
  onOpenLesson,
}: {
  group: KidsClass;
  lessons: KidsLesson[];
  semesterStart: string;
  semesterEnd: string;
  onClose: () => void;
  onSave: (next: KidsClass) => void;
  onOpenLesson: (id:string) => void;
}) {
  const [draft, setDraft] = useState({
    ...group,
    students: group.students.map((item) => ({
      ...item,
      startDate: item.startDate || semesterStart,
    })),
  });
  const [name, setName] = useState("");
  const [startDate, setStartDate] = useState(semesterStart);
  const [lessonSummary,setLessonSummary]=useState<"COMPLETED"|"CANCELLED"|null>(null);
  const classLessons=lessons
    .filter(lesson=>lesson.classId===group.id&&lesson.kind!=="REPLACEMENT"&&lesson.date>=semesterStart&&lesson.date<=semesterEnd)
    .sort((a,b)=>a.date.localeCompare(b.date));
  const plannedLessons=classLessons.filter(lesson=>lesson.status!=="HOLIDAY");
  const completedLessons=plannedLessons.filter(lesson=>lesson.status==="COMPLETED");
  const cancelledLessons=plannedLessons.filter(lesson=>lesson.status==="CANCELLED");
  const summaryLessons=lessonSummary==="COMPLETED"?completedLessons:lessonSummary==="CANCELLED"?cancelledLessons:[];
  function add() {
    const clean = name.trim();
    if (!clean) return;
    setDraft((current) => ({
      ...current,
      students: [
        ...current.students,
        {
          id: `kid-${crypto.randomUUID()}`,
          name: clean,
          active: true,
          startDate,
        },
      ].sort((a, b) => localeCompare(a.name, b.name)),
    }));
    setName("");
  }
  return (
    <div className={styles.modalBackdrop}>
      <section className={styles.modal}>
        <div className={styles.modalHead}>
          <div>
            <CategoryDot category={draft.category} />
            <h2>Editar turma</h2>
            <p>{draft.name}</p>
          </div>
          <button onClick={onClose}>×</button>
        </div>
        <div className={styles.classSemesterSummary}>
          <button type="button" onClick={()=>setLessonSummary(current=>current==="COMPLETED"?null:"COMPLETED")} className={lessonSummary==="COMPLETED"?styles.classSemesterActive:""}>
            <strong>{completedLessons.length}</strong>
            <span>Aulas realizadas</span>
          </button>
          <button type="button" onClick={()=>setLessonSummary(current=>current==="CANCELLED"?null:"CANCELLED")} className={lessonSummary==="CANCELLED"?styles.classSemesterActive:""}>
            <strong>{cancelledLessons.length}</strong>
            <span>Aulas canceladas</span>
          </button>
          <div>
            <strong>{plannedLessons.length}</strong>
            <span>Aulas previstas</span>
          </div>
        </div>
        {lessonSummary?<div className={styles.classLessonHistory}>
          <div className={styles.classLessonHistoryHead}><strong>{lessonSummary==="COMPLETED"?"Aulas realizadas":"Aulas canceladas"} no semestre</strong><button type="button" onClick={()=>setLessonSummary(null)}>Fechar lista</button></div>
          {summaryLessons.length?summaryLessons.map(lesson=><button type="button" key={lesson.id} onClick={()=>onOpenLesson(lesson.id)}>
            <span>{formatDate(lesson.date)}</span>
            <small>{statusLabel[lesson.status]}{lesson.status==="CANCELLED"&&cancelReasonText(lesson)?` · ${cancelReasonText(lesson)}`:""}{lesson.theme?` · ${lesson.theme}`:""}</small>
            <b>Abrir</b>
          </button>):<p>Nenhuma aula nesta situação.</p>}
        </div>:null}
        <div className={styles.formGrid}>
          <label>
            Nome da turma
            <input
              value={draft.name}
              onChange={(event) =>
                setDraft((current) => ({
                  ...current,
                  name: event.target.value,
                }))
              }
            />
          </label>
          <label>
            Professor
            <input
              value={draft.teacher}
              onChange={(event) =>
                setDraft((current) => ({
                  ...current,
                  teacher: event.target.value,
                }))
              }
            />
          </label>
          <label>
            Dia
            <select
              value={draft.weekday}
              onChange={(event) =>
                setDraft((current) => ({
                  ...current,
                  weekday: Number(event.target.value),
                }))
              }
            >
              {weekdayLabel.map((label, index) => (
                <option value={index} key={label}>
                  {label}
                </option>
              ))}
            </select>
          </label>
          <label>
            Horário
            <input
              type="time"
              value={draft.startTime}
              onChange={(event) =>
                setDraft((current) => ({
                  ...current,
                  startTime: event.target.value,
                }))
              }
            />
          </label>
          <label>
            Categoria
            <select
              value={draft.category}
              onChange={(event) =>
                setDraft((current) => ({
                  ...current,
                  category: event.target.value as KidsCategory,
                }))
              }
            >
              {Object.entries(categoryLabel).map(([value, label]) => (
                <option value={value} key={value}>
                  {label}
                </option>
              ))}
            </select>
          </label>
        </div>
        <h3>Crianças</h3>
        <div className={styles.studentEdit}>
          {draft.students.filter((student) => student.active).map((student) => (
            <div key={student.id}>
              <input
                value={student.name}
                onChange={(event) =>
                  setDraft((current) => ({
                    ...current,
                    students: current.students.map((item) =>
                      item.id === student.id
                        ? { ...item, name: event.target.value }
                        : item,
                    ),
                  }))
                }
              />
              <input
                aria-label={`Início de ${student.name}`}
                title="Início na turma"
                type="date"
                min={semesterStart}
                value={student.startDate || semesterStart}
                onChange={(event) =>
                  setDraft((current) => ({
                    ...current,
                    students: current.students.map((item) =>
                      item.id === student.id
                        ? { ...item, startDate: event.target.value }
                        : item,
                    ),
                  }))
                }
              />
              <label>
                <input
                  type="checkbox"
                  checked={student.active}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      students: current.students.map((item) =>
                        item.id === student.id
                          ? { ...item, active: event.target.checked }
                          : item,
                      ),
                    }))
                  }
                />{" "}
                Ativo
              </label>
            </div>
          ))}
        </div>
        <div className={styles.addStudent}>
          <input
            value={name}
            onChange={(event) => setName(event.target.value)}
            placeholder="Nome da criança"
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                add();
              }
            }}
          />
          <label>
            Início na turma
            <input
              type="date"
              min={semesterStart}
              value={startDate}
              onChange={(event) => setStartDate(event.target.value)}
            />
          </label>
          <button onClick={add}>+ Adicionar</button>
        </div>
        <div className={styles.modalActions}>
          <button onClick={onClose}>Cancelar</button>
          <button
            className={styles.primary}
            onClick={() =>
              onSave({
                ...draft,
                name: kidsClassName(
                  draft.category,
                  draft.weekday,
                  draft.startTime,
                ),
                updatedAt: new Date().toISOString(),
              })
            }
          >
            Salvar turma
          </button>
        </div>
      </section>
    </div>
  );
}

function StudentEditor({
  studentId,
  data,
  classes,
  lessons,
  replacements,
  semesterStart,
  onClose,
  onOpenClass,
  onSave,
}: {
  studentId: string;
  data: KidsData;
  classes: KidsClass[];
  lessons: KidsLesson[];
  replacements: KidsReplacement[];
  semesterStart: string;
  onClose: () => void;
  onOpenClass: (id: string) => void;
  onSave: (classes: KidsClass[]) => void;
}) {
  const [draft, setDraft] = useState(
    classes.map((group) => ({
      ...group,
      students: group.students.map((student) => ({ ...student })),
    })),
  );
  const source = classes
    .flatMap((group) => group.students)
    .find((student) => student.id === studentId);
  const [profile, setProfile] = useState<KidsStudent>({
    ...source!,
    name: source?.name || "",
  });
  const [historyFilter,setHistoryFilter]=useState<"present"|"absent"|"pending"|"replaced"|"cancelled"|null>(null);
  useEffect(()=>{
    const saved=window.history.state?.dmpKidsHistoryFilter;
    if(saved?.studentId===studentId&&saved?.start===data.semesterStart&&saved?.end===data.semesterEnd&&["present","absent","pending","replaced","cancelled"].includes(saved?.filter))setHistoryFilter(saved.filter);
    else setHistoryFilter(null);
  },[studentId,data.semesterStart,data.semesterEnd]);
  useEffect(()=>{
    window.history.replaceState({...window.history.state,dmpKidsHistoryFilter:{studentId,start:data.semesterStart,end:data.semesterEnd,filter:historyFilter}},"",window.location.href);
  },[historyFilter,studentId,data.semesterStart,data.semesterEnd]);
  const [newClassId, setNewClassId] = useState("");
  const [newStartDate, setNewStartDate] = useState(semesterStart);
  const memberships = draft.filter((group) =>
    group.students.some(
      (student) => student.id === studentId && student.active,
    ),
  );
  const available = draft.filter(
    (group) =>
      !group.students.some(
        (student) => student.id === studentId && student.active,
      ),
  );
  function patchMembership(
    groupId: string,
    patch: { startDate?: string; active?: boolean },
  ) {
    setDraft((current) =>
      current.map((group) =>
        group.id === groupId
          ? {
              ...group,
              students: group.students.map((student) =>
                student.id === studentId ? { ...student, ...patch } : student,
              ),
            }
          : group,
      ),
    );
  }
  function addMembership() {
    if (!newClassId || !source) return;
    setDraft((current) =>
      current.map((group) => {
        if (group.id !== newClassId) return group;
        const existing = group.students.find(
          (student) => student.id === studentId,
        );
        return {
          ...group,
          students: existing
            ? group.students.map((student) =>
                student.id === studentId
                  ? {
                      ...student,
                      ...profile,
                      startDate: newStartDate,
                      active: true,
                    }
                  : student,
              )
            : [
                ...group.students,
                {
                  ...source,
                  ...profile,
                  startDate: newStartDate,
                  active: true,
                },
              ].sort((a, b) => localeCompare(a.name, b.name)),
        };
      }),
    );
    setNewClassId("");
  }
  function save() {
    const updated = draft.map((group) => ({
      ...group,
      students: group.students.map((student) =>
        student.id === studentId
          ? {
              ...student,
              ...profile,
              name: profile.name.trim() || student.name,
              active:profile.active ? student.active : false,
            }
          : student,
      ),
      updatedAt: new Date().toISOString(),
    }));
    onSave(updated);
  }
  async function pickContact(target: "father" | "mother") {
    const nav = navigator as Navigator & {
      contacts?: {
        select: (
          fields: string[],
          options: { multiple: boolean },
        ) => Promise<Array<{ name?: string[]; tel?: string[] }>>;
      };
    };
    if (!nav.contacts?.select) {
      alert(
        "Neste aparelho, use o preenchimento manual ou importe pelo arquivo de contatos.",
      );
      return;
    }
    try {
      const selected = await nav.contacts.select(["name", "tel"], {
        multiple: false,
      });
      const contact = selected[0];
      if (!contact) return;
      setProfile((current) => ({
        ...current,
        [`${target}Name`]:
          contact.name?.[0] || current[`${target}Name` as keyof KidsStudent],
        [`${target}Phone`]:
          contact.tel?.[0] || current[`${target}Phone` as keyof KidsStudent],
      }));
    } catch {}
  }
  const studentHistory=kidsStudentHistory({...data,classes:draft},studentId);
  const {present,absent}=studentHistory.metrics;
  const historyItems=[
    ...draft.filter(group=>group.students.some(student=>student.id===studentId)).map(group=>{
      const member=group.students.find(student=>student.id===studentId)!;
      return {indicator:undefined,date:member.startDate||semesterStart,type:"Turma",title:`Entrada em ${group.name}`,detail:`Bola ${categoryLabel[group.category]} · ${weekdayLabel[group.weekday]}, ${group.startTime}${member.active?"":" · turma anterior/inativa"}`};
    }),
    ...studentHistory.rows,
  ].filter(item=>(!historyFilter||item.indicator===historyFilter)&&item.date>=data.semesterStart&&item.date<=data.semesterEnd).sort((a,b)=>b.date.localeCompare(a.date));
  function printStudentReport() {
    printReport(buildReport({ ...data, classes: draft }, "student", studentId));
  }
  return (
    <div className={styles.modalBackdrop}>
      <section className={styles.modal}>
        <div className={styles.modalHead}>
          <div>
            <span className={styles.categoryDots}>
              {memberships.map((group) => (
                <CategoryDot key={group.id} category={group.category} />
              ))}
            </span>
            <h2>Dados da criança</h2>
            <p>
              {memberships.length} turma{memberships.length === 1 ? "" : "s"} ·{" "}
              {present} presenças · {absent} faltas
            </p>
            <button onClick={printStudentReport}>
              🖨️ Baixar relatório PDF
            </button>
          </div>
          <button onClick={onClose}>×</button>
        </div>
        <div className={styles.formGrid}>
          <label>
            Nome da criança
            <input
              value={profile.name}
              onChange={(event) =>
                setProfile((current) => ({
                  ...current,
                  name: event.target.value,
                }))
              }
            />
          </label>
          <label>
            Data de nascimento
            {profile.birthDate ? (
              <small>Idade atual: {ageFromBirth(profile.birthDate)} anos</small>
            ) : null}
            <input
              type="date"
              value={profile.birthDate || ""}
              onChange={(event) =>
                setProfile((current) => ({
                  ...current,
                  birthDate: event.target.value,
                }))
              }
            />
          </label>
          <label>
            Situação do cadastro
            <select value={profile.active?"ACTIVE":"INACTIVE"} onChange={event=>setProfile(current=>({...current,active:event.target.value==="ACTIVE"}))}>
              <option value="ACTIVE">Aluno ativo</option>
              <option value="INACTIVE">Aluno inativo</option>
            </select>
            <small>Ao inativar, a criança sai de todas as turmas e chamadas futuras, sem apagar o histórico.</small>
          </label>
          <label>
            Nome do pai
            <input
              value={profile.fatherName || ""}
              onChange={(event) =>
                setProfile((current) => ({
                  ...current,
                  fatherName: event.target.value,
                }))
              }
            />
            <button onClick={() => void pickContact("father")}>
              Buscar nos contatos
            </button>
          </label>
          <label>
            Telefone do pai
            <input
              type="tel"
              value={profile.fatherPhone || ""}
              onChange={(event) =>
                setProfile((current) => ({
                  ...current,
                  fatherPhone: event.target.value,
                }))
              }
            />
            {profile.fatherPhone ? (()=>{const wa=whatsappNumber(profile.fatherPhone);return (
              <span>
                <a href={`tel:${profile.fatherPhone}`}>Ligar</a>
                {wa.href?<> · <a href={wa.href} target="_blank" rel="noreferrer">WhatsApp</a></>:null}
                {wa.missingDdd?<> · Falta o DDD para usar o WhatsApp.</>:null}
              </span>
            );})() : null}
          </label>
          <label>
            Nome da mãe
            <input
              value={profile.motherName || ""}
              onChange={(event) =>
                setProfile((current) => ({
                  ...current,
                  motherName: event.target.value,
                }))
              }
            />
            <button onClick={() => void pickContact("mother")}>
              Buscar nos contatos
            </button>
          </label>
          <label>
            Telefone da mãe
            <input
              type="tel"
              value={profile.motherPhone || ""}
              onChange={(event) =>
                setProfile((current) => ({
                  ...current,
                  motherPhone: event.target.value,
                }))
              }
            />
            {profile.motherPhone ? (()=>{const wa=whatsappNumber(profile.motherPhone);return (
              <span>
                <a href={`tel:${profile.motherPhone}`}>Ligar</a>
                {wa.href?<> · <a href={wa.href} target="_blank" rel="noreferrer">WhatsApp</a></>:null}
                {wa.missingDdd?<> · Falta o DDD para usar o WhatsApp.</>:null}
              </span>
            );})() : null}
          </label>
          <label>
            Valor mensal
            <input
              type="number"
              min="0"
              step="0.01"
              value={profile.monthlyAmount || ""}
              onChange={(event) =>
                setProfile((current) => ({
                  ...current,
                  monthlyAmount: Number(event.target.value) || undefined,
                }))
              }
            />
            <small>{new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(profile.monthlyAmount||0)}</small>
          </label>
          <label>
            Dia do vencimento
            <input
              type="number"
              min="1"
              max="31"
              value={profile.dueDay || ""}
              onChange={(event) =>
                setProfile((current) => ({
                  ...current,
                  dueDay: Number(event.target.value) || undefined,
                }))
              }
            />
          </label>
          <label>
            Forma de cobrança
            <select
              value={profile.billingMode || "RECURRING"}
              onChange={(event) =>
                setProfile((current) => ({
                  ...current,
                  billingMode: event.target.value as KidsStudent["billingMode"],
                }))
              }
            >
              <option value="ONE_TIME">Uma parcela</option>
              <option value="RECURRING">Recorrente</option>
              <option value="INSTALLMENTS">Parcelado</option>
            </select>
          </label>
          {profile.billingMode === "ONE_TIME" ? (
            <label>
              Mês em que a parcela única foi paga
              <input
                type="month"
                value={profile.oneTimePaymentCompetence || ""}
                onChange={(event) =>
                  setProfile((current) => ({
                    ...current,
                    oneTimePaymentCompetence: event.target.value || undefined,
                  }))
                }
              />
              <small>Somente informativo. Não cria nem renova cobrança.</small>
            </label>
          ) : null}
          {profile.billingMode === "INSTALLMENTS" ? (
            <label>
              Quantidade de parcelas
              <input
                type="number"
                min="1"
                value={profile.installmentCount || ""}
                onChange={(event) =>
                  setProfile((current) => ({
                    ...current,
                    installmentCount: Number(event.target.value) || undefined,
                  }))
                }
              />
            </label>
          ) : null}
          <label>
            Observações
            <textarea
              rows={3}
              value={profile.notes || ""}
              onChange={(event) =>
                setProfile((current) => ({
                  ...current,
                  notes: event.target.value,
                }))
              }
            />
          </label>
        </div>
        <section className={styles.studentHistory}>
          <div className={styles.studentHistoryHead}>
            <div>
              <h3>Histórico da criança</h3>
              <p>Linha do tempo do semestre com turmas, aulas, faltas e reposições.</p>
            </div>
            <span>{historyItems.length} registros</span>
          </div>
          <div className={styles.studentHistoryMetrics}>
            {([ ["present","Presenças",present], ["absent","Faltas",absent], ["pending","Reposições pendentes",studentHistory.metrics.pending], ["replaced","Reposições realizadas",studentHistory.metrics.replaced], ["cancelled","Cancelamentos",studentHistory.metrics.cancelled] ] as const).map(([key,label,value])=><button type="button" key={key} aria-pressed={historyFilter===key} onClick={()=>setHistoryFilter(current=>current===key?null:key)}><small>{label}</small><strong>{value}</strong></button>)}
          </div>
          <button type="button" aria-pressed={!historyFilter} onClick={()=>setHistoryFilter(null)}>Todos / Histórico completo</button>
          {profile.notes?.trim()?<div className={styles.studentHistoryNote}><strong>Observação atual</strong><p>{profile.notes}</p></div>:null}
          <div className={styles.timeline}>
            {historyItems.length?historyItems.map((item,index)=><article key={`${item.type}-${item.date}-${index}`}>
              <time>{formatDate(item.date)}</time>
              <span className={styles.timelineDot}/>
              <div><small>{item.type}</small><strong>{item.title}</strong><p>{item.detail}</p></div>
            </article>):<p>Nenhum registro disponível neste filtro e semestre.</p>}
          </div>
        </section>
        <KidsStudentReplacementBalance data={{ ...data, classes: draft }} studentId={studentId} />
        <h3>Turmas da criança</h3>
        <div className={styles.enrollmentList}>
          {memberships.map((group) => {
            const student = group.students.find(
              (item) => item.id === studentId,
            )!;
            return (
              <article key={group.id}>
                <CategoryDot category={group.category} />
                <span>
                  <strong>{group.name}</strong>
                  <small>
                    {weekdayLabel[group.weekday]}, {group.startTime} · Bola{" "}
                    {categoryLabel[group.category]}
                  </small>
                </span>
                <label>
                  Início
                  <input
                    type="date"
                    min={semesterStart}
                    value={student.startDate || semesterStart}
                    onChange={(event) =>
                      patchMembership(group.id, {
                        startDate: event.target.value,
                      })
                    }
                  />
                </label>
                <button onClick={() => onOpenClass(group.id)}>
                  Abrir turma
                </button>
                <button
                  className={styles.removeEnrollment}
                  onClick={() => {
                    if (confirm(`Retirar ${profile.name} de ${group.name}?`))
                      patchMembership(group.id, { active: false });
                  }}
                >
                  Retirar
                </button>
              </article>
            );
          })}
        </div>
        {available.length ? (
          <div className={styles.addEnrollment}>
            <h3>Adicionar em outra turma</h3>
            <select
              value={newClassId}
              onChange={(event) => setNewClassId(event.target.value)}
            >
              <option value="">Selecione a turma</option>
              {available.map((group) => (
                <option key={group.id} value={group.id}>
                  {group.name}
                </option>
              ))}
            </select>
            <label>
              Início na turma
              <input
                type="date"
                min={semesterStart}
                value={newStartDate}
                onChange={(event) => setNewStartDate(event.target.value)}
              />
            </label>
            <button onClick={addMembership} disabled={!newClassId}>
              + Adicionar turma
            </button>
          </div>
        ) : null}
        <div className={styles.modalActions}>
          <button onClick={onClose}>Cancelar</button>
          <button className={styles.primary} onClick={save}>
            Salvar criança
          </button>
        </div>
      </section>
    </div>
  );
}

function Reports({
  data,
  kind,
  setKind,
  reportId,
  setReportId,
  financeData,
}: {
  data: KidsData;
  kind: "student" | "class" | "financial";
  setKind: (value: "student" | "class" | "financial") => void;
  reportId: string;
  setReportId: (value: string) => void;
  financeData: FinanceData | null;
}) {
  const students = useMemo(() => {
    const map = new Map<string, string>();
    data.classes.forEach((group) =>
      group.students
        .filter((item) => item.active)
        .forEach((item) => map.set(item.id, item.name)),
    );
    return [...map].sort((a, b) => localeCompare(a[1], b[1]));
  }, [data.classes]);
  const options =
    kind === "student"
      ? students
      : kind === "class"
        ? data.classes
            .map((item) => [item.id, item.name] as [string, string])
            .sort((a, b) => localeCompare(a[1], b[1]))
        : [];
  const selected = reportId || options[0]?.[0] || "";
  const report = kind==="financial"
    ? buildKidsFinancialReport(data,financeData)
